// Phase 04b: puts the data files (game/data/index.json and the files it lists) back together as
// game/data/gamedata.js, the one script the game loads at start (window.GAMEDATA = ...). gamedata.js is generated:
// it is not in git. `npm run data` runs this; `npm run dev`, `npm run build` and tools/check-quick.py run it too.
//   node tools/build-data.mjs [--out=dir]   (default: game/data)
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { DATA, readGameData } from './data-files.mjs';

export const HEAD =
  '/* Pocket Billies game data, generated by tools/build-data.mjs from the files in game/data (index.json lists them).\n' +
  '   Do not edit this file: edit those files, or use Pocket Billies Studio. */\n';

/* Phase 04b, lazy maps: 98% of the data is the maps' ground and props. In gamedata.js a map (not a room: rooms are small
   and are laid into a place's view at once) has everything but those fields, plus `_lite`: the ground kinds and props
   it uses, so the loader can still fetch their pictures. The game fetches the map's own file (maps/<id>.json) when it
   is needed (js/map-files.js). */
export const MAP_FIELDS = ['heights', 'steps', 'stepm', 'tiles', 'props'];
function lite(sc) {
  if (sc.kind === 'room' || sc.room) return sc;
  const out = {},
    props = new Map();
  for (const [k, v] of Object.entries(sc)) if (!MAP_FIELDS.includes(k)) out[k] = v;
  for (const p of sc.props || []) {
    const q = { k: p.k };
    if (p.v) q.v = p.v;
    if (p.roof) q.roof = p.roof;
    props.set(JSON.stringify(q), q);
  }
  out._lite = { tiles: [...new Set((sc.tiles || []).join(''))].join(''), props: [...props.values()] };
  return out;
}

export function buildData(out = DATA) {
  const D = readGameData();
  D.maps = Object.fromEntries(Object.entries(D.maps).map(([id, sc]) => [id, lite(sc)]));
  const text = HEAD + 'window.GAMEDATA=' + JSON.stringify(D) + ';\n';
  mkdirSync(out, { recursive: true });
  writeFileSync(join(out, 'gamedata.js'), text);
  return text.length;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const o = process.argv.find(a => a.startsWith('--out='));
  const n = buildData(o ? o.slice(6) : DATA);
  console.log(`gamedata.js: ${(n / 1e6).toFixed(2)} MB`);
}
